use std::fs::File;
use std::io::Read;

fn read_user_data() -> Vec<u8> {
    let file = File::open("uploaded_data.txt").unwrap();
    let mut buf = Vec::new();
    // Wrap reader in a 10MB limit
    let mut limited = file.take(10 * 1024 * 1024); 
    limited.read_to_end(&mut buf).unwrap();
    buf
}
